        # back table indexed by x*N//M
        def back(x):
            i = x*N//M if True else 0
            return {'round':round,'floor':math.floor}[br](srgb(i/N)*255)
        out=[back(F[v]) for v in range(256)]
        err=sum(1 for a,b in zip(out,rt) if a!=b)
        best.append((err,M,fr,N,br))
