      /* floor model: F(o) <= F(v)*r < F(o+1) */
      if(o>=1) add(v,o,L);           /* G(o)-G(v) <= L */
      if(o+1<=255) add(o+1,v,-L-eps);  /* G(v)-G(o+1) <= -L-eps */
