        const uint64_t BIG = 65536;

        for (;;)
        {
            dd *= 2;
            if (dd >= (uint32_t) src)
                break;
            n++;
        }
        d->type = F_BILIN;
        d->halvings = n;
        d->n_bilin = dst << n;
        d->ofs = malloc (sizeof (uint16_t) * 2 * d->n_bilin);

        if (src > d->n_bilin)
        {
            step = ((uint64_t) src * BIG) / d->n_bilin;
            ofs = (step - BIG) / 2;
            for (i = 0; i < d->n_bilin; i++)
            {
                uint32_t px = ofs >> 16;
                if (px >= (uint32_t) src - 1)
                {
                    d->ofs [i * 2] = src - 2;
                    d->ofs [i * 2 + 1] = 0;
                }
                else
                {
                    d->ofs [i * 2] = px;
                    d->ofs [i * 2 + 1] = 256 - ((ofs >> 8) & 255);
                }
                ofs += step;
            }
        }
        else
        {
            uint64_t den = d->n_bilin > 1 ? d->n_bilin - 1 : 1;
            for (i = 0; i < d->n_bilin; i++)
            {
                uint32_t px;
                ofs = ((uint64_t) i * (src - 1) * BIG) / den;
                px = ofs >> 16;
                if (px >= (uint32_t) src - 1)
                {
                    d->ofs [i * 2] = src - 2;
                    d->ofs [i * 2 + 1] = 0;
                }
                else
                {
                    d->ofs [i * 2] = px;
                    d->ofs [i * 2 + 1] = 256 - ((ofs >> 8) & 255);
                }
            }
        }
    }
}

static void
dim_free (Dim *d)
{
    free (d->ofs);
}

static inline void
lerp (const Px *p, const Px *q, uint64_t w, Px *out)
{
    int k;
    for (k = 0; k < 4; k++)
        out->c [k] = (p->c [k] * w + q->c [k] * (256 - w)) >> 8;
}

/* Generic 1-D filter over n elements accessed via stride (in Px units) */
static void
filter_1d (const Dim *d, const Px *in, int in_stride, Px *out, int out_stride)
{
    int i, j, k;

    switch (d->type)
    {
    case F_COPY:
        for (i = 0; i < d->dst; i++)
            out [i * out_stride] = in [i * in_stride];
        break;
    case F_ONE:
        for (i = 0; i < d->dst; i++)
            out [i * out_stride] = in [0];
        break;
    case F_BILIN:
    {
        int n = 1 << d->halvings;
        const uint16_t *o = d->ofs;
        for (i = 0; i < d->dst; i++)
        {
            Px acc = { { 0, 0, 0, 0 } };
            for (j = 0; j < n; j++)
            {
                Px r;
                lerp (&in [o [0] * in_stride], &in [(o [0] + 1) * in_stride], o [1], &r);
                for (k = 0; k < 4; k++)
                    acc.c [k] += r.c [k];
                o += 2;
            }
            for (k = 0; k < 4; k++)
                acc.c [k] >>= d->halvings;
            out [i * out_stride] = acc;
        }
        break;
    }
    case F_BOX:
    {
        Px carry = in [0];
        int pos = 1;
        uint64_t fr = 0;
        for (i = 0; i < d->dst; i++)
        {
            uint64_t ofs, w;
            Px acc;
            fr += d->box_step;
            ofs = fr >> 16;
            w = (fr >> 8) & 255;
            acc = carry;
            while (pos < (int) ofs && pos < d->src)
            {
                for (k = 0; k < 4; k++)
                    acc.c [k] += in [pos * in_stride].c [k];
                pos++;
            }
            if ((int) ofs < d->src)
            {
                const Px *r = &in [ofs * in_stride];
                for (k = 0; k < 4; k++)
                {
                    uint64_t s = r->c [k] * w;
                    acc.c [k] += s >> 8;
                    carry.c [k] = ((r->c [k] << 8) - s) >> 8;
                }
                pos = ofs + 1;
            }
            for (k = 0; k < 4; k++)
                out [i * out_stride].c [k] = (acc.c [k] * d->box_mul) >> 16;
        }
        break;
    }
    }
}

static void
unpack_row (const uint8_t *src, int n, Px *out)
{
    int x;
    for (x = 0; x < n; x++)
    {
        uint64_t a = src [x * 4 + 3];
        out [x].c [0] = (uint64_t) lut_from_srgb [src [x * 4]] * a;
        out [x].c [1] = (uint64_t) lut_from_srgb [src [x * 4 + 1]] * a;
        out [x].c [2] = (uint64_t) lut_from_srgb [src [x * 4 + 2]] * a;
        out [x].c [3] = a;
    }
}

static inline void
pack_px (const Px *p, uint8_t *out)
{
    uint64_t a = p->c [3];
    int k;
    if (a > 255) a = 255;
    for (k = 0; k < 3; k++)
    {
        uint64_t u = (p->c [k] * inv_alpha [a]) >> 19;
        if (u > 2047) u = 2047;
        out [k] = lut_to_srgb [u];
    }
    out [3] = (uint8_t) a;
}

void
scale_rgba (const uint8_t *src, int sw, int sh, int sstride,
            uint8_t *dst, int dw, int dh, int dstride)
{
    Dim dx, dy;
    Px *tmp, *rows, *col_in, *col_out;
    int x, y;

    init_inv ();

    if (sw == dw && sh == dh)
    {
        for (y = 0; y < dh; y++)
            memcpy (dst + (size_t) y * dstride, src + (size_t) y * sstride, (size_t) dw * 4);
        return;
    }

    dim_init (&dx, sw, dw);
    dim_init (&dy, sh, dh);

    tmp = malloc (sizeof (Px) * sw);
    rows = malloc (sizeof (Px) * (size_t) dw * sh);

    for (y = 0; y < sh; y++)
    {
        unpack_row (src + (size_t) y * sstride, sw, tmp);
        filter_1d (&dx, tmp, 1, rows + (size_t) y * dw, 1);
    }

    col_out = malloc (sizeof (Px) * dh);
    (void) col_in;
    for (x = 0; x < dw; x++)
    {
        filter_1d (&dy, rows + x, dw, col_out, 1);
        for (y = 0; y < dh; y++)
            pack_px (&col_out [y], dst + (size_t) y * dstride + x * 4);
    }

    free (col_out);
    free (rows);
    free (tmp);
    dim_free (&dx);
    dim_free (&dy);
}

void
scale_rgba_placed (const uint8_t *src, int sw, int sh, int sstride,
                   uint8_t *dst, int dw, int dh, int dstride,
                   int px, int py, int pw, int ph)
{
    int y;
    uint8_t *tmp;
    for (y = 0; y < dh; y++)
        memset (dst + (size_t) y * dstride, 0, (size_t) dw * 4);
    if (pw <= 0 || ph <= 0)
        return;
    tmp = malloc ((size_t) pw * ph * 4);
    scale_rgba (src, sw, sh, sstride, tmp, pw, ph, pw * 4);
    for (y = 0; y < ph; y++)
    {
        if (py + y < 0 || py + y >= dh) continue;
        memcpy (dst + (size_t) (py + y) * dstride + px * 4, tmp + (size_t) y * pw * 4, (size_t) pw * 4);
    }
    free (tmp);
}
