        if (pi.bd == 8 && pi.trns_set) { pi.trns [0] &= 0xff; pi.trns [1] &= 0xff; pi.trns [2] &= 0xff; }
    }
    switch (pi.ct) { case 0: channels = 1; break; case 2: channels = 3; break; case 3: channels = 1; break; case 4: channels = 2; break; case 6: channels = 4; break; default: free (idat); return NULL; }
    bpp_bits = channels * pi.bd;
    inflate_zlib (idat, idat_len, &raw, &raw_len);
    free (idat);
    if (!raw) return NULL;

    pixels = malloc ((size_t) w * h * 4);
    if (!interlace)
    {
        uint8_t *rows;
        size_t rowbytes = ((size_t) w * bpp_bits + 7) / 8;
        int y;
        if (unfilter (raw, raw_len, w, h, bpp_bits, &rows)) { free (raw); free (pixels); return NULL; }
        for (y = 0; y < h; y++)
            convert_row (&pi, rows + y * rowbytes, w, pixels + (size_t) y * w * 4);
        free (rows);
    }
    else
    {
        static const int xs [7] = { 0, 4, 0, 2, 0, 1, 0 }, ys [7] = { 0, 0, 4, 0, 2, 0, 1 };
        static const int dxs [7] = { 8, 8, 4, 4, 2, 2, 1 }, dys [7] = { 8, 8, 8, 4, 4, 2, 2 };
        size_t off = 0;
        int p;
        memset (pixels, 0, (size_t) w * h * 4);
        for (p = 0; p < 7; p++)
        {
            int pw = (w - xs [p] + dxs [p] - 1) / dxs [p];
            int ph = (h - ys [p] + dys [p] - 1) / dys [p];
            size_t rowbytes;
            uint8_t *rows, *tmp;
            int y, x;
            if (w <= xs [p] || h <= ys [p]) continue;
            rowbytes = ((size_t) pw * bpp_bits + 7) / 8;
            if (unfilter (raw + off, raw_len - off, pw, ph, bpp_bits, &rows)) break;
            off += (rowbytes + 1) * ph;
            tmp = malloc ((size_t) pw * 4);
            for (y = 0; y < ph; y++)
            {
                convert_row (&pi, rows + y * rowbytes, pw, tmp);
                for (x = 0; x < pw; x++)
                    memcpy (pixels + ((size_t) (ys [p] + y * dys [p]) * w + xs [p] + x * dxs [p]) * 4, tmp + x * 4, 4);
            }
            free (tmp);
            free (rows);
        }
    }
    free (raw);
    img = image_new ();
    image_add_frame (img, w, h, pixels, 0);
    return img;
}
