    m->sel [m->n_sel++] = s;
    m->compiled = 0;
}

void
symbol_map_add_tags (SymbolMap *m, uint32_t tags, int add)
{
    Selector s;
    memset (&s, 0, sizeof (s));
    s.op = add;
    s.tags = tags;
    push_sel (m, s);
}

static int
parse_hex_cp (const char *s, size_t len, uint32_t *out)
{
    uint32_t v = 0;
    size_t i = 0;
    if (len >= 2 && (s [0] == 'u' || s [0] == 'U') && s [1] == '+') i = 2;
    else if (len >= 1 && (s [0] == 'u' || s [0] == 'U')) i = 1;
    else if (len >= 2 && s [0] == '0' && (s [1] == 'x' || s [1] == 'X')) i = 2;
    if (i >= len) return -1;
    for (; i < len; i++)
    {
        int c = s [i];
        if (!isxdigit (c)) return -1;
        v = v * 16 + (isdigit (c) ? c - '0' : (tolower (c) - 'a' + 10));
        if (v > 0x10ffff) return -1;
    }
    *out = v;
    return 0;
}

static int
parse_token (SymbolMap *m, const char *s, size_t len, int op)
{
    int i;
    Selector sel;
    const char *dots;
    memset (&sel, 0, sizeof (sel));
    sel.op = op;

    if (len == 0) return -2;

    for (i = 0; tag_names [i].name; i++)
    {
        if (len <= strlen (tag_names [i].name) && !strncasecmp (tag_names [i].name, s, len))
        {
            sel.tags = tag_names [i].tags;
            push_sel (m, sel);
            return 0;
        }
    }

    dots = NULL;
    {
        size_t k;
        for (k = 0; k + 1 < len; k++)
            if (s [k] == '.' && s [k + 1] == '.') { dots = s + k; break; }
    }
    if (dots)
    {
        uint32_t a, b;
        if (parse_hex_cp (s, dots - s, &a) || parse_hex_cp (dots + 2, len - (dots - s) - 2, &b))
            return -1;
        sel.is_range = 1;
        sel.first = a;
        sel.last = b;
        push_sel (m, sel);
        return 0;
    }
    else
    {
        uint32_t a;
        if (parse_hex_cp (s, len, &a)) return -1;
        sel.is_range = 1;
        sel.first = sel.last = a;
        push_sel (m, sel);
        return 0;
    }
}

int
symbol_map_apply_spec (SymbolMap *m, const char *spec, char **bad)
{
    const char *p = spec;
    int op = 1;
    int first = 1;

    while (*p)
    {
        const char *start;
        size_t len;
        int r;

        if (*p == '+' || *p == '-' || *p == ',' || *p == ' ')
        {
            int c = *p;
            if (c == '-') op = 0; else op = 1;
            p++;
            if (*p == '+' || *p == '-' || *p == ',')
                return -2;
            if (!*p) break;
        }
        else if (!first)
            op = 1;

        start = p;
        while (*p && *p != '+' && *p != '-' && *p != ',' && *p != ' ') p++;
        len = p - start;
        if (len == 0) continue;
        r = parse_token (m, start, len, op);
        if (r == -1)
        {
            if (bad) { *bad = malloc (len + 1); memcpy (*bad, start, len); (*bad) [len] = 0; }
            return -1;
        }
        if (r) return r;
        first = 0;
    }
    return 0;
}

static int
popc (uint64_t v)
{
    return __builtin_popcountll (v);
}

void
symbol_map_compile (SymbolMap *m)
{
    int i, j;
    free (m->syms);
    m->syms = malloc (sizeof (Symbol) * (N_SYM_DEFS + 1));
    m->n_syms = 0;
    for (i = 0; i < N_SYM_DEFS; i++)
    {
        const SymDef *d = &sym_defs [i];
        int sel = 0;
        for (j = 0; j < m->n_sel; j++)
        {
            const Selector *s = &m->sel [j];
            if (s->is_range)
            {
                if (d->cp >= s->first && d->cp <= s->last)
                {
                    if (s->op && (d->tags & (TAG_BAD | TAG_AMBIGUOUS))) continue;
                    sel = s->op;
                }
            }
            else if (d->tags & s->tags)
                sel = s->op;
        }
        if (sel)
        {
            Symbol *sy = &m->syms [m->n_syms++];
            int k;
            sy->cp = d->cp;
            sy->tags = d->tags;
            sy->cov = d->cov;
            sy->popcount = popc (d->cov);
            for (k = 0; k < 64; k++)
                sy->covp [k] = (d->cov >> (63 - k)) & 1;
        }
    }
    m->compiled = 1;
}
