#define NPIX 64
#define N_CANDIDATES_MAX 8

typedef struct { int idx; int hd; int inv; } Cand;

static inline int
diff_fast (const Color *a, const Color *b)
{
    int d0 = (int) a->ch [0] - (int) b->ch [0];
    int d1 = (int) a->ch [1] - (int) b->ch [1];
    int d2 = (int) a->ch [2] - (int) b->ch [2];
    return d0 * d0 + d1 * d1 + d2 * d2;
}

static int
dominant_channel (const Color *px)
{
    int mn [4] = { 255, 255, 255, 255 }, mx [4] = { 0, 0, 0, 0 };
    int i, j, best = 0, best_range;
    for (i = 0; i < NPIX; i++)
        for (j = 0; j < 4; j++)
        {
            if (px [i].ch [j] < mn [j]) mn [j] = px [i].ch [j];
            if (px [i].ch [j] > mx [j]) mx [j] = px [i].ch [j];
        }
    best_range = mx [0] - mn [0];
    for (j = 1; j < 3; j++)
        if (mx [j] - mn [j] > best_range) { best_range = mx [j] - mn [j]; best = j; }
    return best;
}

static void
sort_by_channel (uint8_t *index, const Color *px, int ch)
{
    static const int gaps [] = { 57, 23, 10, 4, 1 };
    int g, i, j;
    for (g = 0; g < 5; g++)
    {
        int gap = gaps [g];
        for (i = gap; i < NPIX; i++)
        {
            uint8_t t = index [i];
            for (j = i; j >= gap && px [index [j - gap]].ch [ch] > px [t].ch [ch]; j -= gap)
                index [j] = index [j - gap];
            index [j] = t;
        }
    }
}

static uint64_t
cell_bitmap (const Color *px)
{
    uint8_t idx [NPIX];
    int i, ch;
    Color c0, c1;
    uint64_t bm = 0;
    for (i = 0; i < NPIX; i++) idx [i] = i;
    ch = dominant_channel (px);
    sort_by_channel (idx, px, ch);
    c0 = px [idx [NPIX / 4]];        /* "fg" */
    c1 = px [idx [(NPIX * 3) / 4]];  /* "bg" */
    for (i = 0; i < NPIX; i++)
    {
        int e0 = diff_fast (&px [i], &c0);
        int e1 = diff_fast (&px [i], &c1);
        bm <<= 1;
        if (e0 < e1) bm |= 1;
    }
    return bm;
}

static void
insert_cand (Cand *c, int n, int idx, int hd, int inv)
{
    int i = n - 1;
    if (hd >= c [n - 1].hd) return;
    while (i > 0 && c [i - 1].hd > hd)
