#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdio.h>
#include "strbuf.h"
void sb_init (StrBuf *b) { b->s = NULL; b->len = b->cap = 0; }
void sb_free (StrBuf *b) { free (b->s); sb_init (b); }
static void grow (StrBuf *b, size_t n)
{
    if (b->len + n + 1 > b->cap)
    {
        size_t nc = b->cap ? b->cap : 256;
        while (nc < b->len + n + 1) nc *= 2;
        b->s = realloc (b->s, nc);
        b->cap = nc;
    }
}
void sb_addn (StrBuf *b, const char *s, size_t n) { grow (b, n); memcpy (b->s + b->len, s, n); b->len += n; b->s [b->len] = 0; }
void sb_add (StrBuf *b, const char *s) { sb_addn (b, s, strlen (s)); }
void sb_addc (StrBuf *b, char c) { sb_addn (b, &c, 1); }
