{
    va_list ap;
    char tmp [512];
    int n;
    va_start (ap, fmt);
    n = vsnprintf (tmp, sizeof (tmp), fmt, ap);
    va_end (ap);
    if (n < (int) sizeof (tmp)) { sb_addn (b, tmp, n); return; }
    grow (b, n);
    va_start (ap, fmt);
    vsnprintf (b->s + b->len, n + 1, fmt, ap);
    va_end (ap);
    b->len += n;
}
