{
    char u [4];
    if (c < 0x80) { sb_addc (b, (char) c); return; }
    if (c < 0x800) { u [0] = 0xc0 | (c >> 6); u [1] = 0x80 | (c & 0x3f); sb_addn (b, u, 2); return; }
