#include <string.h>
#include "print.h"

typedef struct
{
    int inverse;
    int fg_set, bg_set;
    Color fg, bg;
} Pen;

static int
col_eq (const Color *a, const Color *b)
{
    return a->ch [0] == b->ch [0] && a->ch [1] == b->ch [1] && a->ch [2] == b->ch [2];
}

static void
emit_tc (StrBuf *o, const Pen *want, Pen *cur, int optimize)
{
    int need_fg, need_bg;
    if (!optimize)
    {
        sb_add (o, "\x1b[0m");
        memset (cur, 0, sizeof (*cur));
    }
    if (cur->inverse != want->inverse || (cur->fg_set && !want->fg_set) || (cur->bg_set && !want->bg_set))
    {
        if (cur->inverse || (cur->fg_set && !want->fg_set) || (cur->bg_set && !want->bg_set))
        {
            sb_add (o, "\x1b[0m");
            memset (cur, 0, sizeof (*cur));
        }
        if (want->inverse && !cur->inverse)
        {
            sb_add (o, "\x1b[7m");
            cur->inverse = 1;
        }
    }
    need_fg = want->fg_set && (!cur->fg_set || !col_eq (&cur->fg, &want->fg));
    need_bg = want->bg_set && (!cur->bg_set || !col_eq (&cur->bg, &want->bg));
    if (need_fg && need_bg)
        sb_printf (o, "\x1b[38;2;%d;%d;%d;48;2;%d;%d;%dm", want->fg.ch [0], want->fg.ch [1], want->fg.ch [2],
                   want->bg.ch [0], want->bg.ch [1], want->bg.ch [2]);
    else if (need_fg)
        sb_printf (o, "\x1b[38;2;%d;%d;%dm", want->fg.ch [0], want->fg.ch [1], want->fg.ch [2]);
    else if (need_bg)
        sb_printf (o, "\x1b[48;2;%d;%d;%dm", want->bg.ch [0], want->bg.ch [1], want->bg.ch [2]);
    if (want->fg_set) { cur->fg_set = 1; cur->fg = want->fg; }
    if (want->bg_set) { cur->bg_set = 1; cur->bg = want->bg; }
}

void
print_canvas (const Canvas *cv, StrBuf *out, int optimize)
{
    int x, y;
    Pen cur;
    memset (&cur, 0, sizeof (cur));
    sb_add (out, "\x1b[0m");
    for (y = 0; y < cv->rows; y++)
    {
        for (x = 0; x < cv->cols; x++)
        {
            const Cell *c = &cv->cells [y * cv->cols + x];
            Pen want;
            uint32_t ch = c->c;
            int fgt = c->fg.ch [3] < cv->alpha_threshold;
            int bgt = c->bg.ch [3] < cv->alpha_threshold;
            memset (&want, 0, sizeof (want));
            if (ch == 0) continue;
            if (fgt && bgt) { ch = ' '; }
            else if (fgt) { want.inverse = 1; want.fg_set = 1; want.fg = c->bg; }
            else if (bgt) { want.fg_set = 1; want.fg = c->fg; }
            else { want.fg_set = 1; want.fg = c->fg; want.bg_set = 1; want.bg = c->bg; }
            emit_tc (out, &want, &cur, optimize);
            sb_add_utf8 (out, ch);
        }
        sb_add (out, "\x1b[0m");
        memset (&cur, 0, sizeof (cur));
        sb_addc (out, '\n');
    }
