#define GHASH_H
#include <stdint.h>
/* Simulation of GLib's GHashTable open addressing for direct-hashed integer keys */
typedef struct
{
    int size, mod, mask;
    int nnodes, noccupied;
    uint32_t *hashes;
    uint32_t *keys;
} GHashSim;
void ghs_init (GHashSim *h);
void ghs_free (GHashSim *h);
void ghs_insert (GHashSim *h, uint32_t key);
/* Iteration: fills keys in table order, returns count */
