#include <stdlib.h>
#include <string.h>
#include "ghash.h"

static const int prime_mod [] =
{
    1, 2, 3, 7, 13, 31, 61, 127, 251, 509, 1021, 2039, 4093, 8191, 16381, 32749, 65521,
    131071, 262139, 524287, 1048573, 2097143, 4194301, 8388593, 16777213
};

static void
set_shift (GHashSim *h, int shift)
{
    h->size = 1 << shift;
    h->mod = prime_mod [shift];
    h->mask = h->size - 1;
}

void
ghs_init (GHashSim *h)
{
    memset (h, 0, sizeof (*h));
    set_shift (h, 3);
    h->hashes = calloc (h->size, sizeof (uint32_t));
    h->keys = calloc (h->size, sizeof (uint32_t));
}

void
ghs_free (GHashSim *h)
{
    free (h->hashes);
    free (h->keys);
}

static inline uint32_t
h2i (const GHashSim *h, uint32_t hash)
{
    return (hash * 11u) % (uint32_t) h->mod;
}

static void
resize (GHashSim *h)
{
    int old_size = h->size;
    int n = (int) (h->nnodes * 1.333);
    int shift = 0, i;
    uint8_t *bitmap;
    while (n) { n >>= 1; shift++; }
    if (shift < 3) shift = 3;
    set_shift (h, shift);
    if (h->size > old_size)
    {
        h->hashes = realloc (h->hashes, sizeof (uint32_t) * h->size);
        h->keys = realloc (h->keys, sizeof (uint32_t) * h->size);
        memset (h->hashes + old_size, 0, sizeof (uint32_t) * (h->size - old_size));
        memset (h->keys + old_size, 0, sizeof (uint32_t) * (h->size - old_size));
    }
    bitmap = calloc (h->size > old_size ? h->size : old_size, 1);
    for (i = 0; i < old_size; i++)
    {
        uint32_t nh = h->hashes [i], key;
        if (nh < 2) { h->hashes [i] = 0; continue; }
        if (bitmap [i]) continue;
        h->hashes [i] = 0;
        key = h->keys [i];
        h->keys [i] = 0;
        for (;;)
        {
            uint32_t hv = h2i (h, nh), rep;
            int step = 0;
            while (bitmap [hv]) { step++; hv = (hv + step) & h->mask; }
            bitmap [hv] = 1;
            rep = h->hashes [hv];
            h->hashes [hv] = nh;
            if (rep < 2) { h->keys [hv] = key; break; }
            nh = rep;
            { uint32_t t = h->keys [hv]; h->keys [hv] = key; key = t; }
        }
    }
    free (bitmap);
    h->noccupied = h->nnodes;
}

void
ghs_insert (GHashSim *h, uint32_t key)
{
    uint32_t hash = key < 2 ? 2 : key;
    uint32_t idx = h2i (h, hash), nh;
    int step = 0;
    nh = h->hashes [idx];
    while (nh != 0)
    {
        if (nh == hash && h->keys [idx] == key) return;
        step++;
        idx = (idx + step) & h->mask;
        nh = h->hashes [idx];
    }
    h->hashes [idx] = hash;
    h->keys [idx] = key;
    h->nnodes++;
    h->noccupied++;
    if ((h->size > h->nnodes * 4 && h->size > 8) || (h->size <= h->noccupied + (h->noccupied / 16)))
        resize (h);
}

int
ghs_items (const GHashSim *h, uint32_t *out)
{
    int i, n = 0;
    for (i = 0; i < h->size; i++)
        if (h->hashes [i] >= 2)
            out [n++] = h->keys [i];
    return n;
}
