        break;
    }
    case O_FORMAT:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "symbols") || !strcasecmp (t, "symbol") || !strcasecmp (t, "ansi")) o->format = FMT_SYMBOLS;
        else if (!strcasecmp (t, "sixels") || !strcasecmp (t, "sixel")) o->format = FMT_SIXELS;
        else if (!strcasecmp (t, "kitty")) o->format = FMT_KITTY;
        else if (!strcasecmp (t, "iterm") || !strcasecmp (t, "iterm2")) o->format = FMT_ITERM;
        else die ("Output format given as '%s'. Must be one of [iterm, kitty, sixels, symbols].", val);
        free (t);
        break;
    }
    case O_OPTIMIZE:
        parse_int_arg (val, optname, &i);
        if (i < 0 || i > 9)
        {
            fprintf (stderr, "%s: Optimization level %d is not in the range [0-9].\n", prg, i);
            exit (2);
        }
        o->optimize = i;
        break;
    case O_RELATIVE: if (!parse_bool (val, &o->relative)) die ("Relative positioning must be one of [on, off].", NULL); break;
    case O_PASSTHROUGH:
    {
        char *t = trim (val);
        if (strcasecmp (t, "auto") && strcasecmp (t, "none") && strcasecmp (t, "screen") && strcasecmp (t, "tmux"))
            die ("Passthrough must be one of [auto, none, screen, tmux].", NULL);
        free (t);
        break;
    }
    case O_POLITE: if (!parse_bool (val, &o->polite)) die ("Polite mode must be one of [on, off].", NULL); break;
    case O_ALIGN:
        if (!parse_align (val, &o->halign, &o->valign))
        {
            fprintf (stderr, "%s: Unknown alignment specifier \"%s\".\n", prg, val);
            exit (2);
        }
        break;
    case O_CLEAR: o->clear = 1; break;
    case O_EXACT:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "auto")) o->exact_size = -1;
        else if (!parse_bool (t, &o->exact_size)) die ("Exact size selector must be one of [on, off, auto].", NULL);
        free (t);
        break;
    }
    case O_FITW: o->fit_width = 1; break;
    case O_FONTRATIO:
        if (!parse_fraction (val, &d) || d <= 0) die ("Font ratio must be specified as a positive real number or fraction.", NULL);
        o->font_ratio = d;
        break;
    case O_GRID:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "auto")) { o->grid_cols = -1; o->grid_rows = -1; }
        else
        {
            int w, h;
            if (!parse_size (t, &w, &h))
                die ("Grid size must be specified as [width]x[height], [width]x or x[height], e.g 4x4, 4x or x4.", NULL);
            o->grid_cols = w; o->grid_rows = h;
        }
        free (t);
        break;
    }
    case O_G: o->grid_cols = -1; o->grid_rows = -1; break;
    case O_LABEL: if (!parse_bool (val, &o->label)) die ("Label mode must be one of [on, off].", NULL); break;
    case O_L: o->label = 1; break;
    case O_LINK:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "auto")) o->link = -1;
        else if (!parse_bool (t, &o->link)) die ("Link mode must be one of [auto, on, off].", NULL);
        free (t);
        break;
    }
    case O_MBOTTOM: parse_int_arg (val, optname, &o->margin_bottom); break;
    case O_MRIGHT: parse_int_arg (val, optname, &o->margin_right); break;
    case O_SCALE:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "max")) o->scale = 1e9;
        else if (parse_fraction (t, &d) && d > 0) o->scale = d;
        else die ("Scale must be specified as a positive real number or fraction.", NULL);
        free (t);
        break;
    }
    case O_SIZE:
        if (!parse_size (val, &o->width, &o->height))
            die ("Size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.", NULL);
        break;
    case O_STRETCH: o->stretch = 1; break;
    case O_VIEW:
        if (!parse_size (val, &o->view_width, &o->view_height))
            die ("View size must be specified as [width]x[height], [width]x or x[height], e.g 80x25, 80x or x25.", NULL);
        break;
    case O_ANIMATE: if (!parse_bool (val, &o->animate)) die ("Animate mode must be one of [on, off].", NULL); break;
    case O_DURATION:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "inf") || !strcasecmp (t, "infinite")) o->duration = INFINITY;
        else if (parse_fraction (t, &d) && d >= 0) o->duration = d;
        else die ("Duration must be a positive real number or fraction, \"inf\" or \"infinite\".", NULL);
        free (t);
        break;
    }
    case O_SPEED:
    {
        char *t = trim (val);
        size_t n = strlen (t);
        if (!strcasecmp (t, "max")) o->speed = 1e9;
        else if (n > 3 && !strcasecmp (t + n - 3, "fps"))
        {
            t [n - 3] = 0;
            if (parse_fraction (t, &d) && d > 0) o->speed = -d;
            else die ("Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero.", NULL);
        }
        else if (parse_fraction (t, &d) && d > 0) o->speed = d;
        else die ("Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero.", NULL);
        free (t);
        break;
    }
    case O_WATCH: o->watch = 1; break;
    case O_BG:
        if (!parse_color (val, &o->bg_color)) die ("Unrecognized background color '%s'.", val);
        o->bg_set = 1;
        break;
    case O_FG:
        if (!parse_color (val, &o->fg_color)) die ("Unrecognized foreground color '%s'.", val);
        o->fg_set = 1;
        break;
    case O_COLORS:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "none")) o->mode = MODE_FGBG;
        else if (!strcmp (t, "2")) o->mode = MODE_FGBG_BGFG;
        else if (!strcmp (t, "8")) o->mode = MODE_8;
        else if (!strcmp (t, "16/8")) o->mode = MODE_16_8;
        else if (!strcmp (t, "16")) o->mode = MODE_16;
        else if (!strcmp (t, "240")) o->mode = MODE_240;
        else if (!strcmp (t, "256")) o->mode = MODE_256;
        else if (!strcasecmp (t, "full") || !strcasecmp (t, "rgb") || !strcasecmp (t, "tc") || !strcasecmp (t, "truecolor")) o->mode = MODE_TRUECOLOR;
        else die ("Colors must be one of [none, 2, 8, 16/8, 16, 240, 256, full].", NULL);
        free (t);
        break;
    }
    case O_CEXTR:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "average")) o->color_extractor = 0;
        else if (!strcasecmp (t, "median")) o->color_extractor = 1;
        else die ("Color extractor must be one of [average, median].", NULL);
        free (t);
        break;
    }
    case O_CSPACE:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "rgb")) o->color_space = 0;
        else if (!strcasecmp (t, "din99d")) o->color_space = 1;
        else die ("Color space must be one of [rgb, din99d].", NULL);
        free (t);
        break;
    }
    case O_DITHER:
    {
        char *t = trim (val);
        if (!strcasecmp (t, "none")) o->dither = 0;
        else if (!strcasecmp (t, "ordered") || !strcasecmp (t, "bayer")) o->dither = 1;
        else if (!strcasecmp (t, "diffusion") || !strcasecmp (t, "fs")) o->dither = 2;
        else if (!strcasecmp (t, "noise")) o->dither = 3;
        else die ("Dither must be one of [none, ordered, diffusion, noise].", NULL);
        free (t);
        break;
    }
    case O_DGRAIN:
    {
        int w, h;
        if (!parse_size (val, &w, &h)) die ("Grain dimensions must be specified as [width]x[height], [width]x or x[height], e.g 4x4, 4x or x4.", NULL);
        if (w < 0) w = h;
        if (h < 0) h = w;
        if ((w != 1 && w != 2 && w != 4 && w != 8) || (h != 1 && h != 2 && h != 4 && h != 8))
            die ("Grain dimensions must be exactly 1, 2, 4 or 8.", NULL);
        o->dither_grain_w = w; o->dither_grain_h = h;
        break;
    }
    case O_DINT:
        if (!parse_fraction (val, &d) || d < 0) die ("Dither intensity must be a positive real number or fraction.", NULL);
        o->dither_intensity = d;
        break;
    case O_INVERT: o->invert = 1; break;
    case O_PREPROC: if (!parse_bool (val, &o->preprocess)) die ("Preprocessing must be one of [on, off].", NULL); break;
    case O_THRESH:
        if (!parse_fraction (val, &d) || d < 0 || d > 1) die ("Opacity threshold must be a real number or fraction in the range [0.0-1.0].", NULL);
        o->threshold = d;
        break;
    case O_THREADS: parse_int_arg (val, optname, &o->threads); break;
    case O_WORK:
        parse_int_arg (val, optname, &i);
        if (i < 1 || i > 9) die ("Work factor must be in the range [1-9].", NULL);
        o->work = i;
        break;
    case O_FGONLY: o->fg_only = 1; break;
    case O_FILL:
    case O_SYMBOLS:
    {
        SymbolMap *m = id == O_FILL ? &o->fill : &o->symbols;
        char *bad = NULL;
        int r;
        symbol_map_clear (m);
        symbol_map_init (m);
        r = symbol_map_apply_spec (m, val, &bad);
        if (r == -1) die ("Unrecognized symbol tag '%s'.", bad);
        if (r == -2) die ("Syntax error in symbol tag selectors.", NULL);
        if (id == O_FILL) o->fill_set = 1; else o->symbols_set = 1;
        break;
    }
    case O_GLYPH: o->glyph_file = val; break;
    }
}

int
parse_options (Options *o, int argc, char **argv)
{
    int i, no_more = 0;
    memset (o, 0, sizeof (*o));
    prg = argv [0];
    o->argv0 = argv [0];
    o->format = FMT_AUTO;
    o->optimize = -1;
    o->relative = -1;
    o->halign = o->valign = -1;
    o->exact_size = -1;
    o->font_ratio = -1;
    o->link = -1;
    o->margin_bottom = -1;
    o->margin_right = -1;
    o->scale = -1;
    o->width = o->height = -1;
    o->view_width = o->view_height = -1;
    o->animate = 1;
    o->duration = -1;
    o->speed = 1.0;
    o->mode = -1;
    o->dither = -1;
    o->dither_grain_w = o->dither_grain_h = -1;
    o->dither_intensity = 1.0;
    o->preprocess = -1;
    o->threshold = -1;
    o->threads = -1;
    o->work = 5;
    o->probe = -1;
    symbol_map_init (&o->symbols);
    symbol_map_init (&o->fill);
    o->files = malloc (sizeof (char *) * (argc + 1));

    for (i = 1; i < argc; i++)
    {
        char *a = argv [i];
        if (no_more || a [0] != '-' || a [1] == 0)
        {
            o->files [o->n_files++] = a;
            continue;
        }
        if (a [1] == '-' && a [2] == 0) { no_more = 1; continue; }
        if (a [1] == '-')
        {
            const char *name = a + 2, *eq = strchr (name, '=');
            size_t nlen = eq ? (size_t) (eq - name) : strlen (name);
            const OptDef *d = NULL;
            int k;
            char optname [256];
            for (k = 0; optdefs [k].id; k++)
                if (optdefs [k].long_name && strlen (optdefs [k].long_name) == nlen && !strncmp (optdefs [k].long_name, name, nlen))
                    { d = &optdefs [k]; break; }
            snprintf (optname, sizeof (optname), "--%.*s", (int) nlen, name);
            if (!d)
            {
                fprintf (stderr, "%s: Unknown option %s\n", prg, a);
                exit (2);
            }
            if (d->arg == A_NONE)
            {
                if (eq)
                {
                    fprintf (stderr, "%s: Unexpected argument for %s\n", prg, optname);
                    exit (2);
                }
                handle (o, d->id, NULL, optname);
            }
            else
            {
                const char *val;
                if (eq) val = eq + 1;
                else if (i + 1 < argc) val = argv [++i];
                else
                {
                    fprintf (stderr, "%s: Missing argument for %s\n", prg, optname);
                    exit (2);
                }
                handle (o, d->id, val, optname);
            }
        }
        else
        {
            int j;
            for (j = 1; a [j]; j++)
            {
                const OptDef *d = NULL;
                int k;
                char optname [4] = { '-', a [j], 0, 0 };
                for (k = 0; optdefs [k].id; k++)
                    if (optdefs [k].short_name == a [j]) { d = &optdefs [k]; break; }
                if (!d)
                {
                    fprintf (stderr, "%s: Unknown option -%c\n", prg, a [j]);
                    exit (2);
                }
                if (d->arg == A_NONE)
                    handle (o, d->id, NULL, optname);
                else
                {
                    const char *val;
                    if (a [j + 1]) val = a + j + 1;
                    else if (i + 1 < argc) val = argv [++i];
                    else
                    {
                        fprintf (stderr, "%s: Missing argument for %s\n", prg, optname);
                        exit (2);
                    }
                    handle (o, d->id, val, optname);
                    break;
                }
            }
        }
    }
    return 0;
}
