cat > /workspace/src/options.c <<'EOF'
/* Command line parsing in the style of GLib's GOption */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <math.h>
#include "options.h"
#include "colornames.h"
#include "helptext.h"

static const char *prg;

static void
die (const char *fmt, const char *arg)
{
    fprintf (stderr, "%s: ", prg);
    fprintf (stderr, fmt, arg);
    fprintf (stderr, "\n");
    exit (2);
}

static char *
trim (const char *s)
{
    char *r;
    size_t n;
    while (*s && isspace ((unsigned char) *s)) s++;
    r = strdup (s);
    n = strlen (r);
    while (n > 0 && isspace ((unsigned char) r [n - 1])) r [--n] = 0;
    return r;
}

static int
parse_bool (const char *s, int *out)
{
    char *t = trim (s);
    int r = 0;
    if (!strcasecmp (t, "on") || !strcasecmp (t, "yes") || !strcasecmp (t, "true") || !strcmp (t, "1")) { *out = 1; r = 1; }
    else if (!strcasecmp (t, "off") || !strcasecmp (t, "no") || !strcasecmp (t, "false") || !strcmp (t, "0")) { *out = 0; r = 1; }
    free (t);
    return r;
}

/* Parse real number or fraction a/b */
static int
parse_fraction (const char *s, double *out)
{
    char *t = trim (s), *end, *slash;
    double a, b = 1.0;
    int ok = 0;
    slash = strchr (t, '/');
    if (slash) *slash = 0;
    a = strtod (t, &end);
    if (end != t && *end == 0)
    {
        ok = 1;
        if (slash)
        {
            char *e2;
            b = strtod (slash + 1, &e2);
            if (e2 == slash + 1 || *e2 || b == 0.0) ok = 0;
        }
    }
    free (t);
    if (ok) *out = a / b;
    return ok;
}

static int
parse_size (const char *s, int *w, int *h)
{
    char *t = trim (s), *x, *end;
    int ok = 1;
    long a = -1, b = -1;
    x = strchr (t, 'x');
    if (!x) x = strchr (t, 'X');
    if (!x)
    {
        if (!*t) ok = 0;
        else { a = strtol (t, &end, 10); if (*end || a <= 0) ok = 0; }
    }
    else
    {
        *x = 0;
        if (*t) { a = strtol (t, &end, 10); if (*end || a <= 0) ok = 0; }
        if (x [1]) { b = strtol (x + 1, &end, 10); if (*end || b <= 0) ok = 0; }
        if (a < 0 && b < 0) ok = 0;
    }
    free (t);
    if (ok) { *w = (int) a; *h = (int) b; }
    return ok;
}

int
parse_color (const char *s, uint32_t *out)
{
    char *t = trim (s), *p, *q;
    int i;
    for (p = q = t; *p; p++)
        if (!isspace ((unsigned char) *p)) *q++ = tolower ((unsigned char) *p);
    *q = 0;
    for (i = 0; named_colors [i].name; i++)
    {
        if (!strcmp (named_colors [i].name, t))
        {
            *out = ((uint32_t) named_colors [i].r << 16) | (named_colors [i].g << 8) | named_colors [i].b;
            free (t);
            return 1;
        }
    }
    p = t;
    if (*p == '#') p++;
    else if (p [0] == '0' && p [1] == 'x') p += 2;
    {
        size_t n = strlen (p), k;
        unsigned long v;
        if (n < 6 || n > 8) { free (t); return 0; }
        for (k = 0; k < n; k++) if (!isxdigit ((unsigned char) p [k])) { free (t); return 0; }
        v = strtoul (p, NULL, 16);
        *out = (uint32_t) (v & 0xffffff);
    }
    free (t);
    return 1;
}

static int
parse_align (const char *s, int *ha, int *va)
{
    char *t = strdup (s), *tok, *save = NULL;
    int ok = 1;
    for (tok = strtok_r (t, ",", &save); tok; tok = strtok_r (NULL, ",", &save))
    {
        char *w = trim (tok);
        if (!strcasecmp (w, "left")) *ha = 0;
        else if (!strcasecmp (w, "right")) *ha = 2;
        else if (!strcasecmp (w, "center") || !strcasecmp (w, "centre")) *ha = 1;
        else if (!strcasecmp (w, "top")) *va = 0;
        else if (!strcasecmp (w, "bottom")) *va = 2;
        else if (!strcasecmp (w, "middle")) *va = 1;
        else if (!strcasecmp (w, "mid"))
        {
            /* "mid" applies to both if alone, else to the unspecified */
            if (*ha < 0) *ha = 1; else *va = 1;
            if (*va < 0) *va = 1;
        }
        else { free (w); ok = 0; break; }
        free (w);
    }
    free (t);
    return ok;
}

