static int
parse_int_arg (const char *val, const char *optname, int *out)
{
    char *end;
    long v;
    errno = 0;
    v = strtol (val, &end, 0);
    if (end == val || *end)
    {
        fprintf (stderr, "%s: Cannot parse integer value ?%s? for %s\n", prg, val, optname);
        exit (2);
    }
    *out = (int) v;
    return 1;
}

static void
handle (Options *o, int id, const char *val, const char *optname)
{
    double d;
    int i;
    switch (id)
    {
    case O_FILES: o->files_path = val; o->files0 = 0; break;
    case O_FILES0: o->files_path = val; o->files0 = 1; break;
