read_stream (FILE *f, size_t *len)
{
    uint8_t *buf = NULL;
    size_t cap = 0, n = 0;
    for (;;)
    {
        size_t r;
        if (n + 65536 > cap) { cap = cap ? cap * 2 : 1 << 20; buf = realloc (buf, cap); }
        r = fread (buf + n, 1, cap - n, f);
        if (r == 0) break;
        n += r;
    }
    *len = n;
    return buf;
}

static int
ceil_div_f (double x)
{
    int r = (int) ceil (x - 1e-9);
    return r < 1 ? 1 : r;
}

/* Library-style geometry: fit src aspect into box (cells). bw/bh < 0 = unset */
static void
calc_geometry (int W, int H, int bw, int bh, double fr, int zoom, int *ow, int *oh)
{
    double sa;
    if (bw < 0 && bh < 0) { bw = 80; bh = 24; }
    if (!zoom)
    {
        if (bw >= 0 && bw > W) bw = W;
        if (bh >= 0 && bh > H) bh = H;
    }
    sa = (double) W / H;
    if (bw < 0) { *ow = ceil_div_f (bh * sa / fr); *oh = bh; return; }
    if (bh < 0) { *ow = bw; *oh = ceil_div_f (bw * fr / sa); return; }
    if (sa > (double) bw / bh * fr) { *ow = bw; *oh = ceil_div_f (bw * fr / sa); }
    else { *ow = ceil_div_f (bh * sa / fr); *oh = bh; }
}

static void
fit_aspect (double aw, double ah, int bw, int bh, int *ow, int *oh)
{
    if (aw * bh > bw * ah) { *ow = bw; *oh = ceil_div_f (bw * ah / aw); }
    else { *ow = ceil_div_f (bh * aw / ah); *oh = bh; }
}

typedef struct
{
    int view_w, view_h;
    double font_ratio;
    double cell_w, cell_h;
} Layout;

static void
compute_canvas (const Options *o, const Layout *L, int W, int H, int *cols, int *rows)
{
    int vw = L->view_w, vh = L->view_h;
    double fr = L->font_ratio;

    if (o->stretch)
    {
        *cols = o->width > 0 ? o->width : vw;
        *rows = o->height > 0 ? o->height : vh;
        return;
    }
    if (o->fit_width)
    {
        calc_geometry (W, H, vw, -1, fr, 1, cols, rows);
        return;
    }
    if (o->width > 0 || o->height > 0)
    {
        int zoom = o->scale >= 1e8;
        calc_geometry (W, H, o->width > 0 ? o->width : -1, o->height > 0 ? o->height : -1, fr, zoom, cols, rows);
        return;
    }
    if (o->scale >= 1e8)
    {
        calc_geometry (W, H, vw == INF_DIM ? -1 : vw, vh == INF_DIM ? -1 : vh, fr, 1, cols, rows);
        return;
    }
    {
        double s = o->scale > 0 ? o->scale : 4.0;
        int nw = ceil_div_f (floor (W * s + 1e-9) / L->cell_w);
        int nh = ceil_div_f (floor (H * s + 1e-9) / L->cell_h);
        if (nw <= vw && nh <= vh) { *cols = nw; *rows = nh; return; }
        fit_aspect (nw, nh, vw, vh, cols, rows);
    }
