static void
compute_placement (int W, int H, int cols, int rows, double cell_w, double cell_h, int stretch, int *pc, int *pr)
{
    double bw = cols * cell_w, bh = rows * cell_h;
    if (stretch) { *pc = cols; *pr = rows; return; }
    if ((double) W * bh > (double) H * bw)
    {
        *pc = cols;
        *pr = ceil_div_f (bw * H / W / cell_h);
    }
    else
    {
        *pr = rows;
        *pc = ceil_div_f (bh * W / H / cell_w);
    }
    if (*pc > cols) *pc = cols;
    if (*pr > rows) *pr = rows;
}

