            data = read_stream (stdin, &len);
            if (len == 0)
            {
                fprintf (stderr, "%s: Failed to open '%s': Could not cache input stream\n", o.argv0, path);
                free (data);
                n_fail++;
                continue;
            }
        }
        else
        {
            FILE *f = fopen (path, "rb");
            if (!f)
            {
                fprintf (stderr, "%s: Failed to open '%s': %s\n", o.argv0, path, strerror (errno));
                n_fail++;
                continue;
            }
            data = read_stream (f, &len);
            fclose (f);
        }
        img = load_any (data, len);
        free (data);
        if (!img || img->n_frames == 0)
        {
            fprintf (stderr, "%s: Failed to open '%s': Unknown file format\n", o.argv0, path);
            n_fail++;
            continue;
        }
        if (i > 0) output_separator (&oc);
        (void) first_out;

        {
            Frame *fr = &img->frames [0];
            compute_canvas (&o, &L, fr->width, fr->height, &cols, &rows);
            compute_placement (fr->width, fr->height, cols, rows, L.cell_w, L.cell_h, o.stretch, &pc, &pr);
            output_image (&oc, img, cols, rows, pc, pr);
