#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include "output.h"
#include "scale.h"
#include "print.h"

static void
flush_out (OutputCtx *oc)
{
    if (oc->out.len)
    {
        fwrite (oc->out.s, 1, oc->out.len, stdout);
        oc->out.len = 0;
    }
    fflush (stdout);
}

void
output_init (OutputCtx *oc, Options *o, TermInfo *ti)
{
    memset (oc, 0, sizeof (*oc));
    oc->o = o;
    oc->ti = ti;
    sb_init (&oc->out);

    oc->format = o->format != FMT_AUTO ? o->format : ti->pixel_format;
    oc->mode = o->mode >= 0 ? o->mode : ti->mode;
    if (o->optimize >= 0) oc->optimize = o->optimize;
    else oc->optimize = (oc->mode == MODE_FGBG) ? 0 : 5;

    if (o->symbols_set) oc->symbols = &o->symbols;
    else
    {
        oc->symbols = &o->symbols;
        symbol_map_init (oc->symbols);
        if (ti->unicode)
        {
            symbol_map_add_tags (oc->symbols, TAG_BLOCK | TAG_BORDER | TAG_SPACE, 1);
            symbol_map_add_tags (oc->symbols, TAG_WIDE, 0);
            if (oc->mode != MODE_FGBG)
                symbol_map_add_tags (oc->symbols, TAG_INVERTED, 0);
        }
        else
        {
            symbol_map_add_tags (oc->symbols, TAG_ASCII, 1);
        }
    }
    oc->fill = o->fill_set ? &o->fill : NULL;

    {
        uint32_t fg = 0xffffff, bg = 0x000000;
        if (o->fg_set) fg = o->fg_color;
        if (o->bg_set) bg = o->bg_color;
        if (o->invert) { uint32_t t = fg; fg = bg; bg = t; }
        oc->fg.ch [0] = fg >> 16; oc->fg.ch [1] = fg >> 8; oc->fg.ch [2] = fg; oc->fg.ch [3] = 255;
        oc->bg.ch [0] = bg >> 16; oc->bg.ch [1] = bg >> 8; oc->bg.ch [2] = bg; oc->bg.ch [3] = 255;
    }
    {
        double t = o->threshold >= 0 ? o->threshold : 0.5;
        oc->alpha_threshold = (int) ((1.0 - t) * 256.0);
    }
    oc->cursor_ctl = ti->has_cursor_ctl && !o->polite && oc->mode != MODE_FGBG;
    if (oc->cursor_ctl)
        sb_add (&oc->out, "\x1b[?25l");
}

void
output_separator (OutputCtx *oc)
{
    sb_addc (&oc->out, '\n');
}

void
output_image (OutputCtx *oc, Image *img, int cols, int rows, int pc, int pr)
{
    Frame *fr = &img->frames [0];
    int W = cols * 8, H = rows * 8;
    uint8_t *px = calloc ((size_t) W * H, 4);
    Canvas cv;

    if (pc == cols && pr == rows)
        scale_rgba (fr->pixels, fr->width, fr->height, fr->width * 4, px, W, H, W * 4);
    else
        scale_rgba_placed (fr->pixels, fr->width, fr->height, fr->width * 4, px, W, H, W * 4, 0, 0, pc * 8, pr * 8);

    memset (&cv, 0, sizeof (cv));
    cv.cols = cols;
    cv.rows = rows;
    cv.mode = oc->mode;
    cv.work = oc->o->work;
    cv.fg_only = oc->o->fg_only;
    cv.symbols = oc->symbols;
    cv.fill = oc->fill;
    cv.fg_color = oc->fg;
    cv.bg_color = oc->bg;
    cv.alpha_threshold = oc->alpha_threshold;
    canvas_draw (&cv, px);
    print_canvas (&cv, &oc->out, oc->optimize);
    free (cv.cells);
    free (px);
    flush_out (oc);
}

void
output_finish (OutputCtx *oc)
{
    if (oc->cursor_ctl)
        sb_add (&oc->out, "\x1b[?25h");
    flush_out (oc);
}
