#include <stdlib.h>
#include "palette.h"

const uint32_t term16 [16] =
{
    0x000000, 0x800000, 0x007000, 0x707000, 0x000070, 0x700070, 0x007070, 0xc0c0c0,
    0x404040, 0xff0000, 0x00ff00, 0xffff00, 0x0000ff, 0xff00ff, 0x00ffff, 0xffffff
};

static const uint8_t cube_lv [6] = { 0x00, 0x5f, 0x87, 0xaf, 0xd7, 0xff };

void
palette_color (int idx, Color *out)
{
    uint32_t v;
    if (idx < 16) v = term16 [idx];
    else if (idx < 232)
    {
        int i = idx - 16;
        v = ((uint32_t) cube_lv [i / 36] << 16) | (cube_lv [(i / 6) % 6] << 8) | cube_lv [i % 6];
    }
    else
    {
        int g = 8 + (idx - 232) * 10;
        v = ((uint32_t) g << 16) | (g << 8) | g;
    }
    out->ch [0] = v >> 16;
    out->ch [1] = v >> 8;
    out->ch [2] = v;
    out->ch [3] = 255;
}

static int
dist (const Color *a, const Color *b)
{
    int d0 = (int) a->ch [0] - b->ch [0], d1 = (int) a->ch [1] - b->ch [1], d2 = (int) a->ch [2] - b->ch [2];
    return d0 * d0 + d1 * d1 + d2 * d2;
}

int
palette_nearest (const Color *c, int first, int last)
{
    int i, best = first, bd = 0x7fffffff;
    for (i = first; i <= last; i++)
    {
        Color p;
        int d;
        palette_color (i, &p);
        d = dist (c, &p);
        if (d < bd) { bd = d; best = i; }
    }
    return best;
}

int
palette_nearest_mode (const Color *c, int mode, int is_bg)
{
    switch (mode)
    {
    case MODE_256: return palette_nearest (c, 0, 255);
    case MODE_240: return palette_nearest (c, 16, 255);
    case MODE_16: return palette_nearest (c, 0, 15);
    case MODE_16_8: return is_bg ? palette_nearest (c, 0, 7) : palette_nearest (c, 0, 15);
    case MODE_8: return palette_nearest (c, 0, 7);
    default: return 0;
    }
}
EOF
