{"command":"cat > /workspace/src/print.c <<'EOF'
#include <string.h>
#include "print.h"

typedef struct
{
    int inverse;
    int fg_set, bg_set;
    Color fg, bg;
    int fgi, bgi;
} Pen;

static int
same_fg (const Pen *a, const Pen *b, int indexed)
{
    if (indexed) return a->fgi == b->fgi;
    return a->fg.ch [0] == b->fg.ch [0] && a->fg.ch [1] == b->fg.ch [1] && a->fg.ch [2] == b->fg.ch [2];
}

static int
same_bg (const Pen *a, const Pen *b, int indexed)
{
    if (indexed) return a->bgi == b->bgi;
    return a->bg.ch [0] == b->bg.ch [0] && a->bg.ch [1] == b->bg.ch [1] && a->bg.ch [2] == b->bg.ch [2];
}

static void
fmt_fg (StrBuf *o, int mode, const Pen *p)
{
    if (mode == MODE_TRUECOLOR)
        sb_printf (o, "38;2;%d;%d;%d", p->fg.ch [0], p->fg.ch [1], p->fg.ch [2]);
    else if (mode == MODE_256 || mode == MODE_240)
        sb_printf (o, "38;5;%d", p->fgi);
    else
        sb_printf (o, "%d", p->fgi < 8 ? 30 + p->fgi : 90 + p->fgi - 8);
}

static void
fmt_bg (StrBuf *o, int mode, const Pen *p)
{
    if (mode == MODE_TRUECOLOR)
        sb_printf (o, "48;2;%d;%d;%d", p->bg.ch [0], p->bg.ch [1], p->bg.ch [2]);
    else if (mode == MODE_256 || mode == MODE_240)
        sb_printf (o, "48;5;%d", p->bgi);
    else
        sb_printf (o, "%d", p->bgi < 8 ? 40 + p->bgi : 100 + p->bgi - 8);
}

static void
emit_pen (StrBuf *o, int mode, const Pen *want, Pen *cur, int optimize)
{
    int need_fg, need_bg;
    int indexed = mode != MODE_TRUECOLOR;
    if (!optimize)
    {
        sb_add (o, "\x1b[0m");
        memset (cur, 0, sizeof (*cur));
    }
    if (cur->inverse != want->inverse || (cur->fg_set && !want->fg_set) || (cur->bg_set && !want->bg_set))
    {
        if (cur->inverse || (cur->fg_set && !want->fg_set) || (cur->bg_set && !want->bg_set))
        {
            sb_add (o, "\x1b[0m");
            memset (cur, 0, sizeof (*cur));
        }
        if (want->inverse && !cur->inverse)
        {
            sb_add (o, "\x1b[7m");
            cur->inverse = 1;
        }
    }
    if (mode == MODE_FGBG_BGFG)
        return;
    need_fg = want->fg_set && (!cur->fg_set || !same_fg (cur, want, indexed));
    need_bg = want->bg_set && (!cur->bg_set || !same_bg (cur, want, indexed));
    if (need_fg || need_bg)
    {
        sb_add (o, "\x1b[");
        if (need_fg) fmt_fg (o, mode, want);
        if (need_fg && need_bg) sb_addc (o, ';');
        if (need_bg) fmt_bg (o, mode, want);
        sb_addc (o, 'm');
    }
    if (want->fg_set) { cur->fg_set = 1; cur->fg = want->fg; cur->fgi = want->fgi; }
    if (want->bg_set) { cur->bg_set = 1; cur->bg = want->bg; cur->bgi = want->bgi; }
}

static void
print_fgbg (const Canvas *cv, StrBuf *out)
{
    int x, y;
    for (y = 0; y < cv->rows; y++)
    {
        for (x = 0; x < cv->cols; x++)
        {
            const Cell *c = &cv->cells [y * cv->cols + x];
            if (c->c == 0) continue;
            sb_add_utf8 (out, c->c);
        }
        sb_addc (out, '\n');
    }
}

void
print_canvas (const Canvas *cv, StrBuf *out, int optimize)
{
    int x, y;
    Pen cur;
    if (cv->mode == MODE_FGBG)
    {
        print_fgbg (cv, out);
        return;
    }
    memset (&cur, 0, sizeof (cur));
    sb_add (out, "\x1b[0m");
    for (y = 0; y < cv->rows; y++)
    {
        for (x = 0; x < cv->cols; x++)
        {
            const Cell *c = &cv->cells [y * cv->cols + x];
            Pen want;
            uint32_t ch = c->c;
            int fgt = c->fg.ch [3] < cv->alpha_threshold;
            int bgt = c->bg.ch [3] < cv->alpha_threshold;
            memset (&want, 0, sizeof (want));
            if (ch == 0) continue;
            if (cv->mode == MODE_FGBG_BGFG)
            {
                if (fgt && bgt) ch = ' ';
                else if (fgt) want.inverse = c->bg_idx == 1 ? 0 : 1;
                else want.inverse = (c->bg_idx == 0);
            }
            else if (fgt && bgt) { ch = ' '; }
            else if (fgt) { want.inverse = 1; want.fg_set = 1; want.fg = c->bg; want.fgi = c->bg_idx; }
            else if (bgt) { want.fg_set = 1; want.fg = c->fg; want.fgi = c->fg_idx; }
            else { want.fg_set = 1; want.fg = c->fg; want.fgi = c->fg_idx; want.bg_set = 1; want.bg = c->bg; want.bgi = c->bg_idx; }
            emit_pen (out, cv->mode, &want, &cur, optimize);
            sb_add_utf8 (out, ch);
        }
        sb_add (out, "\x1b[0m");
        memset (&cur, 0, sizeof (cur));
        sb_addc (out, '\n');
    }
}
EOF
