    return tuple(max(0,min(255,int(f32(P+f32((x-P)*2.0))))) for x in c)
def boostR(c):
    P=math.sqrt(c[0]*c[0]*.299+c[1]*c[1]*.587+c[2]*c[2]*.144)
    return tuple(max(0,min(255,int(P+(x-P)*2.0+0.5))) for x in c)
