/* JPEG decoder (baseline + progressive, Huffman), libjpeg-compatible output
 * (islow IDCT, fancy upsampling, standard YCbCr conversion). */
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "image.h"

typedef struct
{
    uint8_t lookup_len [65536]; /* not used */
} Dummy;

typedef struct
{
    uint8_t bits [17];
    uint8_t vals [256];
    int maxcode [18];
    int valptr [17];
    int mincode [17];
    int present;
} Huff;

typedef struct
{
    int id, h, v, tq;
    int bw, bh;       /* blocks wide/high (padded to MCU) */
    int16_t *coef;    /* bw*bh*64 */
    int dc_tbl, ac_tbl;
    int dc_pred;
    uint8_t *pix;     /* bw*8 x bh*8 samples */
} Comp;

typedef struct
{
    const uint8_t *d;
    size_t len, pos;
    uint32_t bitbuf;
    int bitcnt;
    int marker_hit;
    int width, height, ncomp;
    int progressive;
    Comp comp [4];
    uint16_t qt [4][64];
    Huff dc [4], ac [4];
    int hmax, vmax;
    int mcux, mcuy;
    int restart_interval;
    int eobrun;
    int adobe, adobe_transform;
    int ss, se, ah, al;
    int scomp [4], nscomp;
} Jpg;

static const int zigzag [64] =
{
    0, 1, 8, 16, 9, 2, 3, 10, 17, 24, 32, 25, 18, 11, 4, 5,
    12, 19, 26, 33, 40, 48, 41, 34, 27, 20, 13, 6, 7, 14, 21, 28,
    35, 42, 49, 56, 57, 50, 43, 36, 29, 22, 15, 23, 30, 37, 44, 51,
    58, 59, 52, 45, 38, 31, 39, 46, 53, 60, 61, 54, 47, 55, 62, 63
};

static void
build_huff (Huff *h)
{
    int code = 0, k = 0, l;
    for (l = 1; l <= 16; l++)
    {
        h->valptr [l] = k;
        h->mincode [l] = code;
        code += h->bits [l];
        k += h->bits [l];
        h->maxcode [l] = h->bits [l] ? code - 1 : -1;
        code <<= 1;
    }
    h->maxcode [17] = 0x7fffffff;
    h->present = 1;
}

static int
getbit (Jpg *j)
{
    if (j->bitcnt == 0)
    {
        uint8_t b = 0;
        if (j->marker_hit || j->pos >= j->len) { b = 0; }
        else
        {
            b = j->d [j->pos];
            if (b == 0xff)
            {
                uint8_t n = j->pos + 1 < j->len ? j->d [j->pos + 1] : 0;
                if (n == 0) { j->pos += 2; }
                else { j->marker_hit = 1; b = 0; }
            }
            else j->pos++;
        }
        j->bitbuf = b;
        j->bitcnt = 8;
    }
    j->bitcnt--;
    return (j->bitbuf >> j->bitcnt) & 1;
}

static int
getbits (Jpg *j, int n)
{
    int v = 0;
    while (n--) v = (v << 1) | getbit (j);
    return v;
}

static int
extend (int v, int n)
{
    if (n == 0) return 0;
    if (v < (1 << (n - 1))) v -= (1 << n) - 1;
    return v;
}

static int
decode_huff (Jpg *j, const Huff *h)
{
    int code = 0, l;
    for (l = 1; l <= 16; l++)
    {
        code = (code << 1) | getbit (j);
        if (h->maxcode [l] >= 0 && code <= h->maxcode [l])
            return h->vals [h->valptr [l] + code - h->mincode [l]];
    }
    return 0;
}

static void
reset_bits (Jpg *j)
{
    j->bitcnt = 0;
    j->bitbuf = 0;
}

/* Find and consume an RSTn marker */
static void
handle_restart (Jpg *j)
{
    int i;
    reset_bits (j);
    j->marker_hit = 0;
    while (j->pos + 1 < j->len)
    {
        if (j->d [j->pos] == 0xff && j->d [j->pos + 1] >= 0xd0 && j->d [j->pos + 1] <= 0xd7)
        {
            j->pos += 2;
            break;
        }
        if (j->d [j->pos] == 0xff && j->d [j->pos + 1] != 0 && j->d [j->pos + 1] != 0xff)
            break;
        j->pos++;
    }
    for (i = 0; i < 4; i++) j->comp [i].dc_pred = 0;
    j->eobrun = 0;
}

static void
decode_block_baseline (Jpg *j, Comp *c, int16_t *blk)
{
    int t, k;
    t = decode_huff (j, &j->dc [c->dc_tbl]);
    c->dc_pred += extend (getbits (j, t), t);
    blk [0] = (int16_t) c->dc_pred;
    for (k = 1; k < 64; k++)
    {
        int rs = decode_huff (j, &j->ac [c->ac_tbl]);
        int r = rs >> 4, s = rs & 15;
        if (s == 0)
        {
            if (r == 15) { k += 15; continue; }
            break;
        }
        k += r;
        if (k > 63) break;
        blk [zigzag [k]] = (int16_t) extend (getbits (j, s), s);
    }
}

static void
decode_dc_first (Jpg *j, Comp *c, int16_t *blk)
{
    int t = decode_huff (j, &j->dc [c->dc_tbl]);
    int diff = extend (getbits (j, t), t);
    c->dc_pred += diff;
    blk [0] = (int16_t) (c->dc_pred * (1 << j->al));
}

static void
decode_dc_refine (Jpg *j, int16_t *blk)
{
    if (getbit (j)) blk [0] |= (int16_t) (1 << j->al);
}

static void
decode_ac_first (Jpg *j, Comp *c, int16_t *blk)
{
    int k;
    if (j->eobrun > 0) { j->eobrun--; return; }
    for (k = j->ss; k <= j->se; k++)
    {
        int rs = decode_huff (j, &j->ac [c->ac_tbl]);
        int r = rs >> 4, s = rs & 15;
        if (s == 0)
        {
            if (r < 15)
            {
                j->eobrun = (1 << r) - 1;
                if (r) j->eobrun += getbits (j, r);
                break;
            }
            k += 15;
            continue;
        }
        k += r;
        if (k > 63) break;
        blk [zigzag [k]] = (int16_t) (extend (getbits (j, s), s) * (1 << j->al));
    }
}

static void
decode_ac_refine (Jpg *j, Comp *c, int16_t *blk)
{
    int p1 = 1 << j->al, m1 = -1 * (1 << j->al);
    int k = j->ss;
    if (j->eobrun <= 0)
    {
        for (; k <= j->se; )
        {
            int rs = decode_huff (j, &j->ac [c->ac_tbl]);
            int r = rs >> 4, s = rs & 15;
            int val = 0;
            if (s == 0)
            {
                if (r < 15)
                {
                    j->eobrun = (1 << r);
                    if (r) j->eobrun += getbits (j, r);
                    break;
                }
            }
            else
                val = getbit (j) ? p1 : m1;
            while (k <= j->se)
            {
                int16_t *coef = &blk [zigzag [k]];
                if (*coef != 0)
                {
                    if (getbit (j))
                    {
                        if ((*coef & p1) == 0)
                        {
                            if (*coef >= 0) *coef += p1; else *coef += m1;
                        }
                    }
                }
                else
                {
                    if (r == 0)
                    {
                        if (val) *coef = (int16_t) val;
                        k++;
                        break;
                    }
                    r--;
                }
                k++;
            }
        }
    }
    if (j->eobrun > 0)
    {
        for (; k <= j->se; k++)
        {
            int16_t *coef = &blk [zigzag [k]];
            if (*coef != 0)
            {
                if (getbit (j))
                {
                    if ((*coef & p1) == 0)
                    {
                        if (*coef >= 0) *coef += p1; else *coef += m1;
                    }
                }
            }
        }
        j->eobrun--;
    }
}

static void
decode_scan (Jpg *j)
{
    int mcu, n_mcu;
    int restarts = 0;
    j->eobrun = 0;
    reset_bits (j);
    j->marker_hit = 0;
    if (j->nscomp == 1)
    {
        Comp *c = &j->comp [j->scomp [0]];
        int bw = (j->width * c->h + j->hmax * 8 - 1) / (j->hmax * 8);
        int bh = (j->height * c->v + j->vmax * 8 - 1) / (j->vmax * 8);
        int bx, by;
        n_mcu = 0;
        for (by = 0; by < bh; by++)
            for (bx = 0; bx < bw; bx++)
            {
                int16_t *blk = c->coef + ((size_t) by * c->bw + bx) * 64;
                if (j->restart_interval && n_mcu && n_mcu % j->restart_interval == 0) { handle_restart (j); restarts++; }
                if (!j->progressive) decode_block_baseline (j, c, blk);
                else if (j->ss == 0) { if (j->ah == 0) decode_dc_first (j, c, blk); else decode_dc_refine (j, blk); }
                else { if (j->ah == 0) decode_ac_first (j, c, blk); else decode_ac_refine (j, c, blk); }
                n_mcu++;
            }
    }
    else
    {
        n_mcu = j->mcux * j->mcuy;
        for (mcu = 0; mcu < n_mcu; mcu++)
        {
            int mx = mcu % j->mcux, my = mcu / j->mcux, ci;
            if (j->restart_interval && mcu && mcu % j->restart_interval == 0) { handle_restart (j); restarts++; }
            for (ci = 0; ci < j->nscomp; ci++)
            {
                Comp *c = &j->comp [j->scomp [ci]];
                int x, y;
                for (y = 0; y < c->v; y++)
                    for (x = 0; x < c->h; x++)
                    {
                        int bx = mx * c->h + x, by = my * c->v + y;
                        int16_t *blk = c->coef + ((size_t) by * c->bw + bx) * 64;
                        if (!j->progressive) decode_block_baseline (j, c, blk);
                        else if (j->ah == 0) decode_dc_first (j, c, blk);
                        else decode_dc_refine (j, blk);
                    }
            }
        }
    }
    (void) restarts;
    /* skip to next marker */
    while (j->pos + 1 < j->len && !(j->d [j->pos] == 0xff && j->d [j->pos + 1] != 0 && !(j->d [j->pos + 1] >= 0xd0 && j->d [j->pos + 1] <= 0xd7)))
        j->pos++;
}

