#define DESCALE(x, n) (((x) + (1 << ((n) - 1))) >> (n))

static inline uint8_t
range_limit (int x)
{
    x += 128;
    return x < 0 ? 0 : x > 255 ? 255 : (uint8_t) x;
}

static void
idct_islow (const int16_t *coef, const uint16_t *qt, uint8_t *out, int stride)
