    for (i = 0; i < 8; i++)
    {
        const int16_t *in = coef + i;
        const uint16_t *q = qt + i;
        int32_t *w = ws + i;
        if (in [8] == 0 && in [16] == 0 && in [24] == 0 && in [32] == 0 && in [40] == 0 && in [48] == 0 && in [56] == 0)
        {
            int32_t dc = ((int32_t) in [0] * q [0]) * (1 << PASS1_BITS);
            w [0] = w [8] = w [16] = w [24] = w [32] = w [40] = w [48] = w [56] = dc;
            continue;
        }
