        tmp10 = tmp0 + tmp3;
        tmp13 = tmp0 - tmp3;
        tmp11 = tmp1 + tmp2;
        tmp12 = tmp1 - tmp2;

        tmp0 = (int32_t) in [56] * q [56];
        tmp1 = (int32_t) in [40] * q [40];
        tmp2 = (int32_t) in [24] * q [24];
