        o [7] = range_limit ((int) DESCALE (tmp10 - tmp3, CONST_BITS + PASS1_BITS + 3));
        o [1] = range_limit ((int) DESCALE (tmp11 + tmp2, CONST_BITS + PASS1_BITS + 3));
