static inline uint8_t clampu8 (int x) { return x < 0 ? 0 : x > 255 ? 255 : (uint8_t) x; }

/* Upsample component plane to full size using libjpeg fancy upsampling */
static uint8_t *
upsample (Jpg *j, Comp *c, int outw, int outh)
{
    int cw = c->bw * 8, ch = c->bh * 8;
    int hs = j->hmax / c->h, vs = j->vmax / c->v;
    uint8_t *out = malloc ((size_t) outw * outh);
    int x, y;
    /* component actual dimensions */
    int compw = (j->width * c->h + j->hmax - 1) / j->hmax;
    int comph = (j->height * c->v + j->vmax - 1) / j->vmax;
    (void) cw; (void) ch;

    if (hs == 1 && vs == 1)
    {
        for (y = 0; y < outh; y++)
            memcpy (out + (size_t) y * outw, c->pix + (size_t) y * c->bw * 8, outw);
        return out;
    }
    if (hs == 2 && vs == 1)
    {
        for (y = 0; y < outh; y++)
        {
            const uint8_t *in = c->pix + (size_t) y * c->bw * 8;
            uint8_t *o = out + (size_t) y * outw;
            uint8_t *tmp = malloc (compw * 2 + 2);
            int n = compw, i;
            if (n == 1) { tmp [0] = tmp [1] = in [0]; }
            else
            {
                tmp [0] = in [0];
                tmp [1] = (uint8_t) ((in [0] * 3 + in [1] + 2) >> 2);
                for (i = 1; i < n - 1; i++)
                {
                    int v = in [i] * 3;
                    tmp [i * 2] = (uint8_t) ((v + in [i - 1] + 1) >> 2);
                    tmp [i * 2 + 1] = (uint8_t) ((v + in [i + 1] + 2) >> 2);
                }
                tmp [(n - 1) * 2] = (uint8_t) ((in [n - 1] * 3 + in [n - 2] + 1) >> 2);
                tmp [(n - 1) * 2 + 1] = in [n - 1];
            }
            memcpy (o, tmp, outw);
            free (tmp);
        }
        return out;
    }
    if (hs == 2 && vs == 2)
    {
        int n = compw, i;
        int *sums = malloc (sizeof (int) * (n + 2));
        uint8_t *tmp = malloc (n * 2 + 2);
        for (y = 0; y < outh; y++)
        {
            int sy = y / 2;
            int ny = (y & 1) ? sy + 1 : sy - 1;
            const uint8_t *in0, *in1;
            if (ny < 0) ny = 0;
            if (ny > comph - 1) ny = comph - 1;
            in0 = c->pix + (size_t) sy * c->bw * 8;
            in1 = c->pix + (size_t) ny * c->bw * 8;
            for (i = 0; i < n; i++) sums [i] = in0 [i] * 3 + in1 [i];
            if (n == 1)
            {
                tmp [0] = (uint8_t) ((sums [0] * 4 + 8) >> 4);
                tmp [1] = (uint8_t) ((sums [0] * 4 + 7) >> 4);
            }
            else
            {
                tmp [0] = (uint8_t) ((sums [0] * 4 + 8) >> 4);
                tmp [1] = (uint8_t) ((sums [0] * 3 + sums [1] + 7) >> 4);
                for (i = 1; i < n - 1; i++)
                {
                    tmp [i * 2] = (uint8_t) ((sums [i] * 3 + sums [i - 1] + 8) >> 4);
                    tmp [i * 2 + 1] = (uint8_t) ((sums [i] * 3 + sums [i + 1] + 7) >> 4);
                }
                tmp [(n - 1) * 2] = (uint8_t) ((sums [n - 1] * 3 + sums [n - 2] + 8) >> 4);
                tmp [(n - 1) * 2 + 1] = (uint8_t) ((sums [n - 1] * 4 + 7) >> 4);
            }
            memcpy (out + (size_t) y * outw, tmp, outw);
        }
        free (sums);
        free (tmp);
        return out;
    }
    if (hs == 1 && vs == 2)
    {
        for (y = 0; y < outh; y++)
        {
            int sy = y / 2;
            int ny = (y & 1) ? sy + 1 : sy - 1;
            const uint8_t *in0, *in1;
            int bias = (y & 1) ? 2 : 1;
            if (ny < 0) ny = 0;
            if (ny > comph - 1) ny = comph - 1;
            in0 = c->pix + (size_t) sy * c->bw * 8;
            in1 = c->pix + (size_t) ny * c->bw * 8;
            for (x = 0; x < outw; x++)
                out [(size_t) y * outw + x] = (uint8_t) ((in0 [x] * 3 + in1 [x] + bias) >> 2);
        }
        return out;
    }
    /* Generic: replicate */
    for (y = 0; y < outh; y++)
        for (x = 0; x < outw; x++)
            out [(size_t) y * outw + x] = c->pix [(size_t) (y / vs) * c->bw * 8 + x / hs];
    return out;
}

static int32_t cr_r [256], cb_b [256], cr_g [256], cb_g [256];

static void
init_ycc (void)
{
    static int done = 0;
    int i;
    if (done) return;
    for (i = 0; i < 256; i++)
    {
        int x = i - 128;
        cr_r [i] = (int32_t) ((91881 * x + 32768) >> 16);
        cb_b [i] = (int32_t) ((116130 * x + 32768) >> 16);
        cr_g [i] = -46802 * x;
        cb_g [i] = -22554 * x + 32768;
    }
    done = 1;
}

Image *
load_jpeg (const uint8_t *data, size_t len)
{
    Jpg *j;
    size_t p = 2;
    int ci, frame_ok = 0;
    Image *img;
    uint8_t *planes [4] = { 0 }, *rgba;
    int x, y;

    if (len < 4 || data [0] != 0xff || data [1] != 0xd8) return NULL;
    j = calloc (1, sizeof (Jpg));
    j->d = data;
    j->len = len;

    while (p + 4 <= len)
    {
        int m, L;
        if (data [p] != 0xff) { p++; continue; }
        m = data [p + 1];
        if (m == 0xff) { p++; continue; }
        if (m == 0xd8 || (m >= 0xd0 && m <= 0xd7) || m == 0x01) { p += 2; continue; }
        if (m == 0xd9) break;
        L = (data [p + 2] << 8) | data [p + 3];
        if (p + 2 + L > len) break;
        {
            const uint8_t *s = data + p + 4;
            int sl = L - 2;
            if (m == 0xdb)
            {
                int q = 0;
                while (q < sl)
                {
                    int pq = s [q] >> 4, tq = s [q] & 15, k;
                    q++;
                    for (k = 0; k < 64; k++)
                    {
                        int v = pq ? (s [q + k * 2] << 8) | s [q + k * 2 + 1] : s [q + k];
                        j->qt [tq & 3][zigzag [k]] = (uint16_t) v;
                    }
                    q += pq ? 128 : 64;
                }
            }
            else if (m == 0xc4)
            {
                int q = 0;
                while (q < sl)
                {
                    int tc = s [q] >> 4, th = s [q] & 15, k, n = 0;
                    Huff *h = tc ? &j->ac [th & 3] : &j->dc [th & 3];
                    q++;
                    h->bits [0] = 0;
                    for (k = 1; k <= 16; k++) { h->bits [k] = s [q + k - 1]; n += s [q + k - 1]; }
                    q += 16;
                    if (n > 256) n = 256;
                    memcpy (h->vals, s + q, n);
                    q += n;
                    build_huff (h);
                }
            }
            else if (m == 0xdd)
            {
                j->restart_interval = (s [0] << 8) | s [1];
            }
            else if (m == 0xee && sl >= 12 && !memcmp (s, "Adobe", 5))
            {
                j->adobe = 1;
                j->adobe_transform = s [11];
            }
            else if (m >= 0xc0 && m <= 0xcf && m != 0xc4 && m != 0xc8 && m != 0xcc)
            {
                if (m != 0xc0 && m != 0xc1 && m != 0xc2) { free (j); return NULL; }
                j->progressive = m == 0xc2;
                j->height = (s [1] << 8) | s [2];
                j->width = (s [3] << 8) | s [4];
                j->ncomp = s [5];
                if (j->ncomp != 1 && j->ncomp != 3 && j->ncomp != 4) { free (j); return NULL; }
                if (j->width <= 0 || j->height <= 0) { free (j); return NULL; }
                for (ci = 0; ci < j->ncomp; ci++)
                {
                    j->comp [ci].id = s [6 + ci * 3];
                    j->comp [ci].h = s [7 + ci * 3] >> 4;
                    j->comp [ci].v = s [7 + ci * 3] & 15;
                    j->comp [ci].tq = s [8 + ci * 3] & 3;
                    if (j->comp [ci].h > j->hmax) j->hmax = j->comp [ci].h;
                    if (j->comp [ci].v > j->vmax) j->vmax = j->comp [ci].v;
                }
                j->mcux = (j->width + j->hmax * 8 - 1) / (j->hmax * 8);
                j->mcuy = (j->height + j->vmax * 8 - 1) / (j->vmax * 8);
                for (ci = 0; ci < j->ncomp; ci++)
                {
                    Comp *c = &j->comp [ci];
                    c->bw = j->mcux * c->h;
                    c->bh = j->mcuy * c->v;
                    c->coef = calloc ((size_t) c->bw * c->bh * 64, sizeof (int16_t));
                }
                frame_ok = 1;
            }
            else if (m == 0xda && frame_ok)
            {
                int k;
                j->nscomp = s [0];
                for (k = 0; k < j->nscomp && k < 4; k++)
                {
                    int id = s [1 + k * 2], tbl = s [2 + k * 2];
                    for (ci = 0; ci < j->ncomp; ci++)
                        if (j->comp [ci].id == id)
                        {
                            j->scomp [k] = ci;
                            j->comp [ci].dc_tbl = tbl >> 4 & 3;
                            j->comp [ci].ac_tbl = tbl & 3;
                        }
                }
                j->ss = s [1 + j->nscomp * 2];
                j->se = s [2 + j->nscomp * 2];
                j->ah = s [3 + j->nscomp * 2] >> 4;
                j->al = s [3 + j->nscomp * 2] & 15;
                for (ci = 0; ci < 4; ci++) j->comp [ci].dc_pred = 0;
                j->pos = p + 2 + L;
                decode_scan (j);
                p = j->pos;
                continue;
            }
        }
        p += 2 + L;
    }
    if (!frame_ok) { free (j); return NULL; }

    /* IDCT */
    for (ci = 0; ci < j->ncomp; ci++)
    {
        Comp *c = &j->comp [ci];
        int bx, by;
        c->pix = malloc ((size_t) c->bw * 8 * c->bh * 8);
        for (by = 0; by < c->bh; by++)
            for (bx = 0; bx < c->bw; bx++)
                idct_islow (c->coef + ((size_t) by * c->bw + bx) * 64, j->qt [c->tq],
                            c->pix + ((size_t) by * 8 * c->bw * 8) + bx * 8, c->bw * 8);
        planes [ci] = upsample (j, c, j->width, j->height);
    }

    init_ycc ();
    rgba = malloc ((size_t) j->width * j->height * 4);
    for (y = 0; y < j->height; y++)
        for (x = 0; x < j->width; x++)
        {
            size_t i = (size_t) y * j->width + x;
            uint8_t *o = rgba + i * 4;
            if (j->ncomp == 1)
            {
                o [0] = o [1] = o [2] = planes [0][i];
            }
            else if (j->ncomp == 3)
            {
                int Y = planes [0][i], cb = planes [1][i], cr = planes [2][i];
                int transform = j->adobe ? j->adobe_transform : 1;
                if (transform == 0 && j->adobe)
                {
                    o [0] = Y; o [1] = cb; o [2] = cr;
                }
                else
                {
                    o [0] = clampu8 (Y + cr_r [cr]);
                    o [1] = clampu8 (Y + ((cb_g [cb] + cr_g [cr]) >> 16));
                    o [2] = clampu8 (Y + cb_b [cb]);
                }
            }
            else
            {
                /* CMYK / YCCK (Adobe inverted) */
                int c0 = planes [0][i], c1 = planes [1][i], c2 = planes [2][i], k = planes [3][i];
                if (j->adobe_transform == 2)
                {
                    int Y = c0, cb = c1, cr = c2;
                    c0 = 255 - clampu8 (Y + cr_r [cr]);
                    c1 = 255 - clampu8 (Y + ((cb_g [cb] + cr_g [cr]) >> 16));
                    c2 = 255 - clampu8 (Y + cb_b [cb]);
                }
                o [0] = (uint8_t) (c0 * k / 255);
                o [1] = (uint8_t) (c1 * k / 255);
                o [2] = (uint8_t) (c2 * k / 255);
            }
            o [3] = 255;
        }
    for (ci = 0; ci < j->ncomp; ci++)
    {
        free (planes [ci]);
        free (j->comp [ci].coef);
        free (j->comp [ci].pix);
    }
    img = image_new ();
    image_add_frame (img, j->width, j->height, rgba, 0);
    free (j);
    return img;
}
