{"command":"cat > /workspace/src/gif.c <<'EOF'
/* GIF decoder with frame compositing (disposal methods) */
#include <stdlib.h>
#include <string.h>
#include "image.h"

static int
lzw_decode (const uint8_t *data, size_t len, int min_code, uint8_t *out, size_t out_len)
{
    /* data: concatenated sub-blocks already unpacked */
    int clear = 1 << min_code, eoi = clear + 1;
    int code_size = min_code + 1, next = eoi + 1;
    static uint16_t prefix [4096];
    static uint8_t suffix [4096], stack [4097];
    int old = -1, first = 0;
    size_t bitpos = 0, op = 0;
    int i;
    for (i = 0; i < clear; i++) { prefix [i] = 0xffff; suffix [i] = (uint8_t) i; }
    while (op < out_len)
    {
        int code = 0, sp = 0, c;
        size_t b;
        if (bitpos + code_size > len * 8) break;
        for (b = 0; b < (size_t) code_size; b++)
        {
            size_t bp = bitpos + b;
            code |= ((data [bp >> 3] >> (bp & 7)) & 1) << b;
        }
        bitpos += code_size;
        if (code == clear)
        {
            code_size = min_code + 1;
            next = eoi + 1;
            old = -1;
            continue;
        }
        if (code == eoi) break;
        if (old == -1)
        {
            if (code >= clear) break;
            out [op++] = (uint8_t) code;
            old = code;
            first = code;
            continue;
        }
        c = code;
        if (code >= next)
        {
            if (code > next) break;
            stack [sp++] = (uint8_t) first;
            c = old;
        }
        while (c >= clear)
        {
            if (sp >= 4096) break;
            stack [sp++] = suffix [c];
            c = prefix [c];
        }
        stack [sp++] = (uint8_t) c;
        first = c;
        while (sp > 0 && op < out_len) out [op++] = stack [--sp];
        if (next < 4096)
        {
            prefix [next] = (uint16_t) old;
            suffix [next] = (uint8_t) first;
            next++;
            if (next == (1 << code_size) && code_size < 12) code_size++;
        }
        old = code;
    }
    return (int) op;
}

Image *
load_gif (const uint8_t *d, size_t len)
{
    size_t p;
    int sw, sh, gct_flag, gct_size, bg_index;
    uint8_t gct [768];
    uint8_t *canvas, *prev_canvas = NULL;
    Image *img;
    int trans_index = -1, disposal = 0, delay = 0;
    int last_disposal = 0, lx = 0, ly = 0, lw = 0, lh = 0;
    int have_frame = 0;

    if (len < 13 || (memcmp (d, "GIF87a", 6) && memcmp (d, "GIF89a", 6))) return NULL;
    sw = d [6] | (d [7] << 8);
    sh = d [8] | (d [9] << 8);
    gct_flag = d [10] >> 7;
    gct_size = 2 << (d [10] & 7);
    bg_index = d [11];
    (void) bg_index;
    p = 13;
    if (gct_flag)
    {
        if (p + gct_size * 3 > len) return NULL;
        memcpy (gct, d + p, gct_size * 3);
        p += gct_size * 3;
    }
    if (sw <= 0 || sh <= 0) return NULL;
    img = image_new ();
    img->loop_count = 1;
    canvas = calloc ((size_t) sw * sh, 4);

    while (p < len)
    {
        uint8_t b = d [p++];
        if (b == 0x3b) break;
        if (b == 0x21)
        {
            uint8_t label;
            if (p >= len) break;
            label = d [p++];
            if (label == 0xf9 && p < len && d [p] >= 4)
            {
                disposal = (d [p + 1] >> 2) & 7;
                delay = d [p + 2] | (d [p + 3] << 8);
                trans_index = (d [p + 1] & 1) ? d [p + 4] : -1;
            }
            else if (label == 0xff && p < len && d [p] == 11 && p + 12 < len && !memcmp (d + p + 1, "NETSCAPE2.0", 11))
            {
                size_t q = p + 12;
                if (q + 3 < len && d [q] >= 3 && d [q + 1] == 1)
                    img->loop_count = d [q + 2] | (d [q + 3] << 8);
            }
            while (p < len)
            {
                uint8_t n = d [p++];
                if (n == 0) break;
                p += n;
            }
        }
        else if (b == 0x2c)
        {
            int fx, fy, fw, fh, lct_flag, interlace, lct_size, min_code;
            const uint8_t *ct = gct;
            uint8_t lct [768];
            uint8_t *data = NULL, *idx;
            size_t dlen = 0;
            int x, y, row;
            if (p + 9 > len) break;
            fx = d [p] | (d [p + 1] << 8);
            fy = d [p + 2] | (d [p + 3] << 8);
            fw = d [p + 4] | (d [p + 5] << 8);
            fh = d [p + 6] | (d [p + 7] << 8);
            lct_flag = d [p + 8] >> 7;
            interlace = (d [p + 8] >> 6) & 1;
            lct_size = 2 << (d [p + 8] & 7);
            p += 9;
            if (lct_flag)
            {
                if (p + lct_size * 3 > len) break;
                memcpy (lct, d + p, lct_size * 3);
                ct = lct;
                p += lct_size * 3;
            }
            if (p >= len) break;
            min_code = d [p++];
            while (p < len)
            {
                uint8_t n = d [p++];
                if (n == 0) break;
                if (p + n > len) n = (uint8_t) (len - p);
                data = realloc (data, dlen + n + 1);
                memcpy (data + dlen, d + p, n);
                dlen += n;
                p += n;
            }

            /* Apply previous frame's disposal */
            if (have_frame)
            {
                if (last_disposal == 2)
                {
                    for (y = ly; y < ly + lh && y < sh; y++)
                        for (x = lx; x < lx + lw && x < sw; x++)
                            memset (canvas + ((size_t) y * sw + x) * 4, 0, 4);
                }
                else if (last_disposal == 3 && prev_canvas)
                    memcpy (canvas, prev_canvas, (size_t) sw * sh * 4);
            }
            if (disposal == 3)
            {
                if (!prev_canvas) prev_canvas = malloc ((size_t) sw * sh * 4);
                memcpy (prev_canvas, canvas, (size_t) sw * sh * 4);
            }

            idx = calloc ((size_t) fw * fh + 1, 1);
            if (data && min_code >= 1 && min_code <= 11)
                lzw_decode (data, dlen, min_code, idx, (size_t) fw * fh);
            free (data);

            for (row = 0; row < fh; row++)
            {
                int dy;
                if (interlace)
                {
                    int r = row;
                    if (r < (fh + 7) / 8) dy = r * 8;
                    else if ((r -= (fh + 7) / 8) < (fh + 3) / 8) dy = 4 + r * 8;
                    else if ((r -= (fh + 3) / 8) < (fh + 1) / 4) dy = 2 + r * 4;
                    else { r -= (fh + 1) / 4; dy = 1 + r * 2; }
                }
                else dy = row;
                for (x = 0; x < fw; x++)
                {
                    int ci = idx [(size_t) row * fw + x];
                    int cx = fx + x, cy = fy + dy;
                    uint8_t *o;
                    if (cx >= sw || cy >= sh) continue;
                    if (ci == trans_index) continue;
                    o = canvas + ((size_t) cy * sw + cx) * 4;
                    o [0] = ct [ci * 3];
                    o [1] = ct [ci * 3 + 1];
                    o [2] = ct [ci * 3 + 2];
                    o [3] = 255;
                }
            }
            free (idx);
            {
                uint8_t *fr = malloc ((size_t) sw * sh * 4);
                memcpy (fr, canvas, (size_t) sw * sh * 4);
                image_add_frame (img, sw, sh, fr, delay * 10);
            }
            have_frame = 1;
            last_disposal = disposal;
            lx = fx; ly = fy; lw = fw; lh = fh;
            trans_index = -1;
            disposal = 0;
            delay = 0;
        }
        else
            break;
    }
    free (canvas);
    free (prev_canvas);
    if (img->n_frames == 0) { image_free (img); return NULL; }
    img->is_animation = img->n_frames > 1;
    return img;
